.slider-wrap {
  position: relative; width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  perspective: 1000px; overflow: hidden; touch-action: none;
}
.slide-card {
  position: absolute; width: 220px; height: 280px;
  border-radius: 15px; display: flex; flex-direction: column;
  align-items: center; justify-content: center; font-family: sans-serif;
  transition: transform 0.5s ease, opacity 0.5s ease;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5); cursor: grab;
}
.slide-card:active { cursor: grabbing; }
.bg-1 { background: linear-gradient(135deg, #f6d365, #fda085); color: #000; }
.bg-2 { background: linear-gradient(135deg, #84fab0, #8fd3f4); color: #000; }
.bg-3 { background: linear-gradient(135deg, #a18cd1, #fbc2eb); color: #000; }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;background:transparent;display:flex;align-items:center;justify-content:center;';

const wrap = document.createElement('div');
wrap.className = 'slider-wrap';

const cardsData = [
  { cls: 'bg-1', title: 'Ayurveda' },
  { cls: 'bg-2', title: 'Technology' },
  { cls: 'bg-3', title: 'Animations' }
];

let currentIndex = 0;
const cardEls = [];

cardsData.forEach((data, i) => {
  const card = document.createElement('div');
  card.className = `slide-card ${data.cls}`;
  card.innerHTML = `<h2 style="margin:0">${data.title}</h2>`;
  cardEls.push(card);
  wrap.appendChild(card);
});
c.appendChild(wrap);

function updateCards() {
  cardEls.forEach((card, i) => {
    let offset = i - currentIndex;
    if (offset === 0) {
      card.style.transform = `translateX(0px) translateZ(0px) rotateY(0deg)`;
      card.style.opacity = '1';
      card.style.zIndex = '10';
    } else if (offset > 0) {
      card.style.transform = `translateX(80px) translateZ(-100px) rotateY(-20deg)`;
      card.style.opacity = '0.6';
      card.style.zIndex = '5';
    } else {
      card.style.transform = `translateX(-80px) translateZ(-100px) rotateY(20deg)`;
      card.style.opacity = '0.6';
      card.style.zIndex = '5';
    }
  });
}
updateCards();

let startX = 0;
wrap.addEventListener('pointerdown', (e) => startX = e.clientX);
wrap.addEventListener('pointerup', (e) => {
  let endX = e.clientX;
  if (startX - endX > 50 && currentIndex < cardsData.length - 1) currentIndex++;
  else if (endX - startX > 50 && currentIndex > 0) currentIndex--;
  updateCards();
});
